function (input, customGameData) {
            var node = input.getElementsByTagName("FSInfo")[0];
            if (node) {
                customGameData.freeSpinsRemaining = this.getValueOfAttribute(node, 'fSSpinsRemaining');
                customGameData.totalFreeSpinsWin = this.getValueOfAttribute(node, 'fsWinnings');
                customGameData.reTriggeredSpin = this.getValueOfAttribute(node, 'reTriggeredSpin');
                customGameData.fsRetriggered = this.getValueOfAttribute(node, 'fsRetriggered');
                customGameData.isHansOnFS = (this.getStringValueOfAttribute(node, 'isHansOnFs') == 'Y');
                customGameData.hansSpinsRemaining = this.getValueOfAttribute(node, 'hansSpinRemaining');
                customGameData.bonusGuarantee = this.getValueOfAttribute(node, 'bonusGuarantee');
                customGameData.isMaxWin = customGameData.isMaxWin || (this.getStringValueOfAttribute(node, "isMaxWin") === "Y");
                if (customGameData.isHansOnFS) {
                    customGameData.hansWildPositions = this.getStringValueOfAttribute(node, 'hansWilds').split('|').map(function (item) {
                        return parseInt(item, 10);
                    });
                }
                var currrentStickyWildsString = this.getStringValueOfAttribute(node, 'currentStickyWilds');
                if (currrentStickyWildsString != '')
                    customGameData.currentStickyWilds = this.getStringValueOfAttribute(node, 'currentStickyWilds').split('|').map(function (item) {
                        return parseInt(item, 10);
                    });
                var totalStickyWildsString = this.getStringValueOfAttribute(node, 'totalStickyWilds');
                if (totalStickyWildsString != '')
                    customGameData.totalStickyWilds = this.getStringValueOfAttribute(node, 'totalStickyWilds').split('|').map(function (item) {
                        return parseInt(item, 10);
                    });
            }
        }

