wild.source:
function (input, customGameData, parseForRecovery) {
            if (parseForRecovery === void 0) { parseForRecovery = false; }
            var nodeList = input.getElementsByTagName("WildInfo");
            var node;
            var parentNodeName = parseForRecovery ? "BaseGameRecoveryInfo" : 'GameResult';
            for (var index = 0; index < nodeList.length; index++) {
                if (nodeList[index].parentNode.nodeName == parentNodeName)
                    node = nodeList[index];
            }
            if (!node)
                return;
            var indicesString = this.getStringValueOfAttribute(node, 'Indices');
            if (indicesString.length != 0)
                customGameData.wildReelIndices = indicesString.split('|').map(function (item) {
                    return parseInt(item, 10);
                });
        }

