next.source:
function () {
            var _this = this;
            _super.prototype.execute.call(this);
            var response = this._serverModel.getLogicResponse();
            if (this._statesModel.getCurrentState().stateName == game.GameStates.WIN_DISPLAY_STATE ||
                (this._statesModel.getCurrentState().stateName == game.GameStates.LOGIC_GLS_STATE && response.customGameData.hasWheelBonusStarted)) {
                if (response.customGameData.freeSpinsRemaining <= 0 || response.customGameData.isMaxWin) {
                    if (!response.customGameData.isFreeSpinResponse || response.customGameData.isMaxWin)
                        this._statesModel.gotoNextState();
                    else
                        TweenMax.delayedCall(2, function () { _this.eventDispatcher.dispatchEvent(new game.GameEvent(game.GameEvent.FREESPIN_COMPLETE)); }, null, this);
                }
                else {
                    this._statesModel.changeStateByName(game.GameStates.LOGIC_GLS_STATE);
                    if (this._componentListModel._forceButton && this._componentListModel._forceButton.showToolsBeforeFSStart) {
                        this._componentListModel._forceButton.showHideTools(1);
                        this._componentListModel._forceButton.addEventListener(components.ForceButtonEvent.FORCE_CLOSED, this.onForceClose, this);
                    }
                    else if (response.customGameData.isFreeSpinResponse) {
                        TweenMax.delayedCall(1, function () { _this.eventDispatcher.dispatchEvent(new game.GameEvent(game.GameEvent.FREESPIN_START_SPIN)); }, null, this);
                    }
                    else {
                        this.eventDispatcher.dispatchEvent(new game.GameEvent(game.GameEvent.FREESPIN_START_SPIN));
                    }
                }
            }
        }

