init.source:
function () {
            _super.prototype.execute.call(this);
            var encoders = [];
            if (this._historyModel.getIsHistoryReplay() && !this._server.getInitResponse()) {
                encoders.push(new game.HistoryReplaceEncoder(this._historyModel.getNextState()));
                this._historyModel.restart();
            }
            var initData = new server.GLSRequest(encoders);
            this._server.makeInitRequest(initData);
        }

logic.source:
function () {
            _super.prototype.execute.call(this);
            if (!this._server.getInitResponse().isRecovering) {
                this._partnerAdapter.startedPlay();
            }
            var encoders = [
                new game.StakeEncoder(this._stakesModel.getTotalBet()),
                new server.GLSCurrencyEncoder(this._server.getInitResponse().platformData.currencyMultiplier)
            ];
            var history = this._historyModel.getNextState();
            if (history) {
                encoders.push(new game.HistoryReplaceEncoder(history));
            }
            if (this._forceModel.forceSet || game.DemoData.isDemoSet) {
                encoders.push(new game.ForceEncoder(this._forceModel.reelData.positions, this._forceModel.reelData.index, this._server));
                this._forceModel.reset();
                this._forceModel.forceSet = false;
            }
            var logicData = new server.GLSRequest(encoders);
            var initResponse = this._server.getInitResponse();
            if (!initResponse.isRecovering || ((this._statesModel.getSubGame() == game.SubGames.PRE_GAME) && (this._statesModel.getCurrentState().stateName == game.PreGameStates.INIT))) {
                this._server.makeLogicRequest(logicData);
            }
        }

end.source:
function () {
            _super.prototype.execute.call(this);
            if (!this._historyModel.getIsHistoryReplay()) {
                this._partnerAdapter.finishedPlay();
                this._partnerAdapter.finishedPostGameAnimations();
                this._server.makeEndRequest(new server.GLSRequest([]));
            }
            if (this._autoplayModel.isInProgress()) {
                this._autoplayModel.updateWinAndStake(this._server.getLogicResponse().gameResultData.totalWin, this._stakesModel.getTotalBet());
            }
        }

